-- Run inside BEGIN / ROLLBACK only. No real customer, stock, money or Meta operations.
create temporary table inventory_qa_results(check_name text primary key, passed boolean);
create function pg_temp.qa(ok boolean,label text) returns void language plpgsql as $$
begin if ok is distinct from true then raise exception 'QA FAILED: %',label;end if;insert into inventory_qa_results values(label,true);end $$;
create function pg_temp.reject_qa_detail() returns trigger language plpgsql as $$
begin if new.facebook_page_id='990000000099' then raise exception 'QA injected failure';end if;return new;end $$;
create trigger qa_reject_detail before insert on public.fanpage_inventory_details for each row execute function pg_temp.reject_qa_detail();
do $$
declare a uuid:=gen_random_uuid();u uuid:=gen_random_uuid();p uuid:=gen_random_uuid();x uuid;y uuid;z uuid;o uuid;io uuid;
 r jsonb;input jsonb;before_count bigint;before_ledger bigint;before_audit bigint;code text;failed boolean;
begin
 insert into auth.users(id,email) values(a,'inventory-admin-'||a||'@example.invalid'),(u,'inventory-viewer-'||u||'@example.invalid');
 insert into public.profiles(id,email,display_name,role,status) values(a,'qa-admin@example.invalid','QA admin','super_admin','active'),(u,'qa-viewer@example.invalid','QA viewer','viewer','active') on conflict(id) do update set role=excluded.role,status='active';
 insert into public.sales_products(id,sku,name,unit_price_vnd,status,product_group) values(p,'QA-'||p,'QA rollback only',100000,'active','fanpage');
 input:=jsonb_build_object('product_id',p,'facebook_page_id','990000000001','page_name','QA Page','page_link','https://facebook.com/990000000001','purchase_cost_vnd',10000);
 r:=public.sales_inventory_command('intake',a,input);x:=(r->'item'->>'id')::uuid;
 perform pg_temp.qa((select count(*)=1 from public.fanpage_inventory_details where inventory_item_id=x) and (select count(*)=1 from public.sales_inventory_ledger where inventory_item_id=x),'intake detail and ledger');
 select count(*) into before_count from public.sales_inventory_items;select count(*) into before_ledger from public.sales_inventory_ledger;select count(*) into before_audit from public.admin_audit_logs;
 failed:=false;begin perform public.sales_inventory_command('intake',a,input||'{"facebook_page_id":"000990000000001"}');exception when unique_violation then failed:=true;end;
 perform pg_temp.qa(failed and (select count(*)=before_count from public.sales_inventory_items) and (select count(*)=before_ledger from public.sales_inventory_ledger) and (select count(*)=before_audit from public.admin_audit_logs),'normalized duplicate rolls back all writes');
 failed:=false;begin perform public.sales_inventory_command('intake',a,input||'{"facebook_page_id":"990000000099"}');exception when raise_exception then if sqlerrm='QA injected failure' then failed:=true;else raise;end if;end;
 perform pg_temp.qa(failed and (select count(*)=before_count from public.sales_inventory_items),'injected detail failure leaves no orphan');
 failed:=false;begin perform public.sales_inventory_command('intake',u,input);exception when raise_exception then if sqlerrm='Forbidden' then failed:=true;else raise;end if;end;
 perform pg_temp.qa(failed,'viewer cannot intake');
 perform public.sales_inventory_command('publish',a,jsonb_build_object('inventory_item_id',x));r:=public.sales_inventory_command('publish',a,jsonb_build_object('inventory_item_id',x));
 perform pg_temp.qa((r->>'duplicate')::boolean,'publish retry idempotent');
 code:='FS'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,10));
 input:=jsonb_build_object('product_id',p,'order_code',code,'payment_reference',code,'buyer_name','QA only','buyer_phone','0000000000','buyer_email','qa@example.invalid','quantity',2,'unit_price_vnd',100000,'gross_amount_vnd',200000,'discount_percent',0,'discount_amount_vnd',0,'promo_discount_vnd',0,'expected_amount_vnd',200000,'zero_value_verification_status',null,'payment_expires_at',now()+interval '30 minutes');
 select id into o from public.sales_checkout_create(input,'{}');
 perform pg_temp.qa((select fulfillment_status='page_debt' from public.sales_orders where id=o),'stock shortage creates backorder with debt');
 perform public.sales_inventory_command('cancel_order',a,jsonb_build_object('order_id',o,'reason','QA backorder cancellation'));
 code:='FS'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,10));input:=input||jsonb_build_object('order_code',code,'payment_reference',code);
 select id into o from public.sales_checkout_create(input||'{"quantity":1,"gross_amount_vnd":100000,"expected_amount_vnd":100000}','{}');
 perform pg_temp.qa((select status='reserved' from public.sales_inventory_items where id=x) and (select count(*)=1 from public.sales_invoice_records where order_id=o),'checkout reserves and invoices together');
 update public.profiles set role='operator',permissions='{"sales_inventory":["reserve","release","finalize"]}' where id=u;
 failed:=false;begin perform public.sales_inventory_command('reserve',u,jsonb_build_object('order_id',o,'inventory_item_ids',jsonb_build_array(x)));exception when raise_exception then if sqlerrm='Forbidden' then failed:=true;else raise;end if;end;
 perform pg_temp.qa(failed,'granted staff cannot operate unassigned order');
 insert into public.sales_order_assignments(order_id,assignee_user_id,assigned_by) values(o,u,a);
 perform public.sales_inventory_command('reserve',u,jsonb_build_object('order_id',o,'inventory_item_ids',jsonb_build_array(x)));
 perform pg_temp.qa((select count(*)=1 from public.sales_order_inventory_items where order_id=o),'delegated assigned staff can reserve idempotently');
 update public.profiles set permissions='{}' where id=u;
 failed:=false;begin perform public.sales_inventory_command('release',u,jsonb_build_object('order_id',o,'reason','QA revoke'));exception when raise_exception then if sqlerrm='Forbidden' then failed:=true;else raise;end if;end;
 perform pg_temp.qa(failed and (select status='reserved' from public.sales_inventory_items where id=x),'revoked permission blocks assigned staff');
 update public.profiles set role='viewer' where id=u;
 failed:=false;begin perform public.sales_inventory_command('finalize',a,jsonb_build_object('order_id',o));exception when raise_exception then if sqlerrm like '%payment or verification incomplete%' then failed:=true;else raise;end if;end;
 perform pg_temp.qa(failed,'unpaid cannot finalize');
 update public.sales_orders set payment_status='paid' where id=o;
 perform public.sales_inventory_command('finalize',a,jsonb_build_object('order_id',o));r:=public.sales_inventory_command('finalize',a,jsonb_build_object('order_id',o));
 perform pg_temp.qa((select status='external_sold' from public.sales_inventory_items where id=x) and (r->>'duplicate')::boolean,'external sale and duplicate finalize');
 r:=public.sales_inventory_command('intake',a,jsonb_build_object('product_id',p,'facebook_page_id','990000000002','page_name','QA Inhouse','page_link','https://facebook.com/990000000002'));y:=(r->'item'->>'id')::uuid;
 perform public.sales_inventory_command('publish',a,jsonb_build_object('inventory_item_id',y));
 r:=public.sales_inventory_command('create_inhouse_order',a,jsonb_build_object('product_id',p,'buyer_user_id',u,'quantity',1));io:=(r->>'order_id')::uuid;
 update public.sales_orders set quantity=2 where id=io;
 failed:=false;begin perform public.sales_inventory_command('reserve',a,jsonb_build_object('order_id',io,'destination','inhouse','inventory_item_ids',jsonb_build_array(y,'ffffffff-ffff-ffff-ffff-ffffffffffff')));exception when raise_exception then if sqlerrm like '%does not match product%' then failed:=true;else raise;end if;end;
 perform pg_temp.qa(failed and (select status='available' from public.sales_inventory_items where id=y) and not exists(select 1 from public.sales_order_inventory_items where order_id=io),'batch reserve failure rolls back earlier item');
 update public.sales_orders set quantity=1 where id=io;
 perform public.sales_inventory_command('reserve',a,jsonb_build_object('order_id',io,'destination','inhouse','inventory_item_ids',jsonb_build_array(y)));
 failed:=false;begin perform public.sales_inventory_command('finalize',a,jsonb_build_object('order_id',io));exception when raise_exception then if sqlerrm like '%payment or verification incomplete%' then failed:=true;else raise;end if;end;
 perform pg_temp.qa(failed,'zero order requires verification');
 perform public.sales_inventory_command('verify_zero',a,jsonb_build_object('order_id',io));perform public.sales_inventory_command('finalize',a,jsonb_build_object('order_id',io));r:=public.sales_inventory_command('finalize',a,jsonb_build_object('order_id',io));
 perform pg_temp.qa((select status='inhouse_transferred' from public.sales_inventory_items where id=y) and (select registry_source='sales_inventory' from public.pages where id='990000000002') and (select count(*)=1 from public.inhouse_page_inventory where inventory_item_id=y) and (r->>'duplicate')::boolean,'inhouse creates one registry and warehouse entry');
 failed:=false;begin perform public.sales_inventory_command('assign_inhouse',u,jsonb_build_object('inventory_item_id',y,'user_id',u));exception when raise_exception then if sqlerrm='Forbidden' then failed:=true;else raise;end if;end;
 perform pg_temp.qa(failed,'viewer cannot self assign');
 perform public.sales_inventory_command('assign_inhouse',a,jsonb_build_object('inventory_item_id',y,'user_id',u));perform public.sales_inventory_command('assign_inhouse',a,jsonb_build_object('inventory_item_id',y,'user_id',u));
 perform pg_temp.qa((select count(*)=1 from public.page_assignments where page_id='990000000002' and user_id=u and status='active') and (select count(*)=1 from public.page_access where page_id='990000000002' and user_id=u),'assignment creates access once');
 r:=public.sales_inventory_command('intake',a,jsonb_build_object('product_id',p,'facebook_page_id','990000000003','page_name','QA release','page_link','https://facebook.com/990000000003'));z:=(r->'item'->>'id')::uuid;
 perform public.sales_inventory_command('publish',a,jsonb_build_object('inventory_item_id',z));
 code:='FS'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,10));input:=input||jsonb_build_object('order_code',code,'payment_reference',code,'quantity',1,'gross_amount_vnd',100000,'expected_amount_vnd',100000);
 select id into o from public.sales_checkout_create(input,'{}');
 failed:=false;begin perform public.sales_inventory_command('release',a,jsonb_build_object('order_id',o));exception when raise_exception then if sqlerrm like '%reason required%' then failed:=true;else raise;end if;end;
 perform pg_temp.qa(failed and (select status='reserved' from public.sales_inventory_items where id=z),'release requires reason');
 perform public.sales_inventory_command('cancel_order',a,jsonb_build_object('order_id',o,'reason','QA rollback'));
 perform pg_temp.qa((select status='available' from public.sales_inventory_items where id=z) and (select payment_status='cancelled' from public.sales_orders where id=o) and (select invoice_status='cancelled' from public.sales_invoice_records where order_id=o),'cancel releases stock order invoice atomically');
 perform pg_temp.qa(not has_function_privilege('anon','public.sales_inventory_command(text,uuid,jsonb)','EXECUTE') and not has_function_privilege('authenticated','public.sales_checkout_create(jsonb,jsonb)','EXECUTE') and has_function_privilege('service_role','public.sales_inventory_command(text,uuid,jsonb)','EXECUTE'),'RPC service only');
 perform pg_temp.qa(not has_table_privilege('authenticated','public.sales_order_inventory_items','SELECT,INSERT,UPDATE,DELETE'),'no client grants for order stock links');
end $$;
select * from inventory_qa_results order by check_name;
